"""
Execution-grounded verification of agent-authored workspaces.

This module implements the ExecutionHarness which verifies code by actually
running it (parsing, installing, importing, testing) rather than relying on
textual analysis or file counts.
"""

import ast
import os
import sys
import subprocess
import tempfile
import shutil
import time
import re
import tomllib
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module if available, otherwise define fallbacks
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        filter_bundle,
        partition_bundle,
        count_source_files,
        EXCLUDED_DIR_SEGMENTS,
        EXCLUDED_DIR_SUFFIXES
    )
except ImportError:
    # Fallback definitions if artifacts.py is not yet available or import fails
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {
            k: v for k, v in bundle.items()
            if not is_generated_path(k) and not is_malformed_path(k)
        }

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        filtered = filter_bundle(bundle)
        return sum(1 for k in filtered if k.endswith(tuple(suffixes)))


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = sum(1 for g in evaluated if g.passed)
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [
            f"Verification Report ({self.source})",
            f"Authored Files: {self.authored_files} (Python: {self.python_files})",
            f"Score Penalty: {self.score_penalty:.2f}",
            "-" * 40
        ]
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"[{status_icon}] {g.name:10} : {g.status:7} ({g.method})")
            if g.detail:
                lines.append(f"    Detail: {g.detail}")
        lines.append("-" * 40)
        lines.append(f"Pass Rate (Evaluated): {self.pass_rate:.2%}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "gate_status": self.gate_status,
            "pass_rate": self.pass_rate
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    if not text:
        return {}

    # Regex to match fenced code blocks with optional language and optional filename hint
    # Pattern: ```[lang] [filename]\n content \n```
    # We look for lines that look like filenames in the fence header or just use sequential naming if not found.
    # Common pattern in agent outputs: ```python path/to/file.py

    blocks = {}
    # Split by ```
    parts = re.split(r'```', text)

    # parts[0] is prose before first block
    # parts[1] is content of first block (including header line)
    # parts[2] is prose between blocks
    # etc.

    file_counter = 0
    for i in range(1, len(parts), 2):
        block_content = parts[i]
        if not block_content:
            continue

        lines = block_content.splitlines()
        if not lines:
            continue

        header = lines[0].strip()
        code_lines = lines[1:]

        # Try to extract filename from header
        # Header might be "python", "python src/main.py", "src/main.py", etc.
        filename = None
        tokens = header.split()
        for token in tokens:
            if '.' in token and not token.startswith('-'):
                # Heuristic: if it looks like a path with extension
                if any(token.endswith(ext) for ext in ['.py', '.toml', '.cfg', '.txt', '.md', '.json', '.yaml', '.yml']):
                    filename = token
                    break

        if not filename:
            # If no filename found, generate one
            filename = f"extracted_file_{file_counter}.py"
            file_counter += 1

        # Clean up filename (remove leading slashes if any)
        filename = filename.lstrip('/')

        content = "\n".join(code_lines)
        blocks[filename] = content

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict-like
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'

        # If bundle is empty, try extracting from deliverable text
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        if not bundle:
            # Empty workspace
            return self._create_empty_report(source)

        return self.verify_bundle(bundle, source=source)

    def _create_empty_report(self, source: str) -> VerificationReport:
        gates = [
            GateResult(name='syntax', status=FAILED, method='ast_parse', detail='No Python files found'),
            GateResult(name='build', status=FAILED, method='metadata_check', detail='No build metadata found'),
            GateResult(name='smoke', status=FAILED, method='import_check', detail='No modules to import'),
            GateResult(name='tests', status=FAILED, method='pytest_run', detail='No tests found'),
            GateResult(name='telemetry', status=FAILED, method='ast_analysis', detail='No telemetry code found'),
        ]
        failed_count = sum(1 for g in gates if g.status == FAILED)
        penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=penalty,
            authored_files=0,
            python_files=0,
            source=source,
            harness_version='3.0-execution'
        )

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to get authored files
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, ('.py',))

        # Create temp directory
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files to temp dir
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            # Run verification on the directory
            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory for files
            authored = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]

                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        full_path = os.path.join(root, file)
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                content = f.read()
                            authored[rel_path] = content
                        except Exception:
                            pass

        authored_files = len(authored)
        python_files = count_source_files(authored, ('.py',))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source,
            harness_version='3.0-execution'
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        py_files = [p for p in authored.keys() if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='No Python files found',
                duration_s=time.time() - start_time
            )

        errors = []
        for path in py_files:
            full_path = os.path.join(workdir, path)
            try:
                with open(full_path, 'r', encoding='utf-8') as f:
                    content = f.read()
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")
            except Exception as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start_time
        if errors:
            return GateResult(
                name='syntax',
                status=FAILED,
                method='ast_parse',
                detail='Syntax errors found: ' + '; '.join(errors[:5]),
                duration_s=duration,
                evidence={'errors': errors}
            )

        return GateResult(
            name='syntax',
            status=PASSED,
            method='ast_parse',
            detail=f"All {len(py_files)} Python files parsed successfully",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()

        # Check for metadata files
        metadata_files = ['pyproject.toml', 'setup.py', 'setup.cfg']
        found_metadata = None

        for mf in metadata_files:
            if mf in authored:
                found_metadata = mf
                break

        if not found_metadata:
            return GateResult(
                name='build',
                status=FAILED,
                method='metadata_check',
                detail='No build metadata (pyproject.toml, setup.py, setup.cfg) found',
                duration_s=time.time() - start_time
            )

        # Validate pyproject.toml if present
        if 'pyproject.toml' in authored:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)

                # Check for required tables
                has_project = 'project' in data
                has_build_system = 'build-system' in data
                has_tool = 'tool' in data

                if not (has_project or has_build_system or has_tool):
                    return GateResult(
                        name='build',
                        status=FAILED,
                        method='toml_validation',
                        detail='pyproject.toml is valid TOML but missing [project], [build-system], or [tool] tables',
                        duration_s=time.time() - start_time
                    )
            except Exception as e:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='toml_validation',
                    detail=f'pyproject.toml is invalid: {e}',
                    duration_s=time.time() - start_time
                )

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run(
                [self.python_executable, '-m', 'pip', '--version'],
                capture_output=True,
                timeout=10
            )
        except Exception:
            return GateResult(
                name='build',
                status=SKIPPED,
                method='pip_install',
                detail='pip not available or failed to check version',
                duration_s=time.time() - start_time
            )

        try:
            # Run pip install -e . --no-deps --no-build-isolation
            result = subprocess.run(
                [self.python_executable, '-m', 'pip', 'install', '-e', '.', '--no-deps', '--no-build-isolation'],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start_time

            if result.returncode == 0:
                return GateResult(
                    name='build',
                    status=PASSED,
                    method='pip_install',
                    detail='Package installed successfully',
                    duration_s=duration
                )
            else:
                return GateResult(
                    name='build',
                    status=FAILED,
                    method='pip_install',
                    detail=f'pip install failed: {result.stderr[:500]}',
                    duration_s=duration,
                    evidence={'stderr': result.stderr, 'stdout': result.stdout}
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail='pip install timed out',
                duration_s=time.time() - start_time
            )
        except Exception as e:
            return GateResult(
                name='build',
                status=FAILED,
                method='pip_install',
                detail=f'pip install error: {e}',
                duration_s=time.time() - start_time
            )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()

        # Find non-test modules
        # Exclude test files and __init__.py? Spec says "Non-test authored modules"
        # Usually test files are named test_*.py or *_test.py
        modules = []
        for path in authored.keys():
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path)
            if 'test' in basename.lower():
                continue
            if basename == '__init__.py':
                continue
            modules.append(path)

        if not modules:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='No importable non-test modules found',
                duration_s=time.time() - start_time
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Try importing each module in a subprocess
        # We can try to import them all in one go or individually.
        # Individually is safer to identify which one fails.

        import_errors = []
        module_not_found_errors = []

        for mod_path in modules:
            # Convert path to module name
            # e.g., src/foo/bar.py -> foo.bar
            # e.g., foo/bar.py -> foo.bar

            rel_path = mod_path
            if rel_path.startswith('src/'):
                rel_path = rel_path[4:]

            module_name = rel_path.replace('/', '.').replace('\\', '.')
            if module_name.endswith('.py'):
                module_name = module_name[:-3]

            # Skip if module name is empty or invalid
            if not module_name or module_name.startswith('.') or module_name.endswith('.'):
                continue

            try:
                # Run python -c "import module"
                result = subprocess.run(
                    [self.python_executable, '-c', f'import {module_name}'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=10
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    if 'ModuleNotFoundError' in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it might be skipped.
                        # The spec says: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
                        # This implies if the module itself imports fine but a dependency fails, it's skipped.
                        # But if the module itself is not found, it's failed.

                        # Heuristic: If the error is about the module we are trying to import, it's a failure.
                        # If it's about a dependency, it's a skip candidate.
                        # However, distinguishing this is hard without parsing the traceback.
                        # Let's assume if the module name is in the error, it's a failure.
                        if module_name in stderr or f"No module named '{module_name}'" in stderr:
                            import_errors.append(f"{module_name}: Module not found")
                        else:
                            module_not_found_errors.append(f"{module_name}: Dependency missing")
                    else:
                        import_errors.append(f"{module_name}: {stderr[:200]}")

            except subprocess.TimeoutExpired:
                import_errors.append(f"{module_name}: Timeout")
            except Exception as e:
                import_errors.append(f"{module_name}: {e}")

        duration = time.time() - start_time

        if import_errors:
            return GateResult(
                name='smoke',
                status=FAILED,
                method='import_check',
                detail='Import failures: ' + '; '.join(import_errors[:5]),
                duration_s=duration,
                evidence={'errors': import_errors}
            )

        if module_not_found_errors:
            return GateResult(
                name='smoke',
                status=SKIPPED,
                method='import_check',
                detail='Skipped due to missing third-party dependencies: ' + '; '.join(module_not_found_errors[:5]),
                duration_s=duration,
                evidence={'skipped_reasons': module_not_found_errors}
            )

        return GateResult(
            name='smoke',
            status=PASSED,
            method='import_check',
            detail=f"All {len(modules)} modules imported successfully",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()

        # Find test files
        test_files = []
        for path in authored.keys():
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path)
            if 'test' in basename.lower():
                test_files.append(path)

        if not test_files:
            return GateResult(
                name='tests',
                status=FAILED,
                method='pytest_run',
                detail='No test files found',
                duration_s=time.time() - start_time
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"

        env = os.environ.copy()
        env['PYTHONPATH'] = python_path

        # Check if pytest is available and functional
        use_pytest = False
        try:
            # Verify pytest can actually run a trivial collection
            check_result = subprocess.run(
                [self.python_executable, '-m', 'pytest', '--collect-only', '-q', '--no-header', '-p', 'no:cacheprovider'],
                cwd=workdir,
                env=env,
                capture_output=True,
                text=True,
                timeout=10
            )
            # If collection fails with import errors, pytest might be broken or deps missing
            # But if it returns 0 or 5 (no tests collected), it is functional
            if check_result.returncode in (0, 5):
                use_pytest = True
        except Exception:
            use_pytest = False

        if use_pytest:
            try:
                # Run pytest
                # We need to specify the test files or directory
                # Using the workdir as rootdir
                result = subprocess.run(
                    [self.python_executable, '-m', 'pytest', '-v', '--tb=short', '-p', 'no:cacheprovider'],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                duration = time.time() - start_time

                if result.returncode == 0:
                    return GateResult(
                        name='tests',
                        status=PASSED,
                        method='pytest_run',
                        detail='All tests passed',
                        duration_s=duration
                    )
                else:
                    # Check if it failed due to ModuleNotFoundError
                    stderr = result.stderr
                    stdout = result.stdout
                    combined = stderr + stdout

                    if 'ModuleNotFoundError' in combined:
                        # Check if it's a third-party package
                        # If pytest itself failed to import, it's a skip? No, we checked pytest version.
                        # If a test file failed to import due to missing dep, it's a skip.
                        # If tests ran but failed, it's a failure.

                        # Heuristic: If "ModuleNotFoundError" is present and no tests were collected/run, it might be a skip.
                        # If tests were collected and failed, it's a failure.

                        # Let's look for "collected" in stdout
                        if "collected" in stdout and "error" in stderr.lower():
                             # Tests collected but error during collection or execution
                             # If the error is ModuleNotFoundError, it's likely a dependency issue
                             if "ModuleNotFoundError" in stderr:
                                 return GateResult(
                                    name='tests',
                                    status=SKIPPED,
                                    method='pytest_run',
                                    detail='Tests skipped due to missing dependencies',
                                    duration_s=duration,
                                    evidence={'stderr': stderr[:500]}
                                )

                        # If we are here, it's a failure
                        return GateResult(
                            name='tests',
                            status=FAILED,
                            method='pytest_run',
                            detail=f'Tests failed: {stderr[:500]}',
                            duration_s=duration,
                            evidence={'stderr': stderr, 'stdout': stdout}
                        )

                    return GateResult(
